// Pokémon Champions — the current Ranked Battle Regulation and what is usable
// under it. Pure: data + date arithmetic, no React, no DOM. The id list is
// generated by scripts/gen-champions-roster.mjs from committed Serebii rows
// (scripts/data/champions-usable.json); see that script for the semantics.
//
// Why a dated window and not just a list: Champions rotates Regulations
// roughly quarterly and adds species and Megas with each one. A legality
// filter that quietly keeps saying "Regulation M-C" in February is worse than
// none, so the UI reads `regulationStatus()` and says when the window closed.

import regulationRaw from '@/data/champions-regulation.json';

export interface ChampionsSeason {
  id: string;
  start: string; // YYYY-MM-DD, inclusive
  end: string;   // YYYY-MM-DD, exclusive (the next season starts that day)
}

export interface ChampionsRegulation {
  id: string;            // 'm-c'
  label: string;         // 'Regulation M-C'
  game: 'champions';
  start: string;         // YYYY-MM-DD
  end: string;           // YYYY-MM-DD (exclusive)
  seasons: ChampionsSeason[];
  source: string;        // Serebii page the rows were captured from
  fetched: string;       // YYYY-MM-DD the rows were captured
  ids: number[];         // Trainer's Codex entry ids usable under the regulation
}

export const CHAMPIONS_REGULATION = regulationRaw as ChampionsRegulation;

/** Entry ids usable in Champions Ranked under the current Regulation. */
export const CHAMPIONS_USABLE_IDS: ReadonlySet<number> = new Set(CHAMPIONS_REGULATION.ids);

export function isUsableInChampions(id: number): boolean {
  return CHAMPIONS_USABLE_IDS.has(id);
}

/** Format-preset id for the current regulation: `champions-m-c`. */
export const CHAMPIONS_PRESET_ID = `champions-${CHAMPIONS_REGULATION.id}`;

/** 'Regulation M-C' → 'Reg. M-C' for chip labels. */
export function shortRegulationLabel(reg: ChampionsRegulation = CHAMPIONS_REGULATION): string {
  return reg.label.replace(/^Regulation\s+/, 'Reg. ');
}

const DAY_MS = 86_400_000;
const utcDate = (ymd: string) => new Date(`${ymd}T00:00:00Z`);

export type RegulationPhase = 'upcoming' | 'active' | 'ended';

export interface RegulationStatus {
  phase: RegulationPhase;
  /** Whole days until the window closes (negative once it has). */
  daysLeft: number;
  /** The season the date falls in, when the regulation publishes seasons. */
  season?: ChampionsSeason;
}

export function regulationStatus(
  reg: ChampionsRegulation = CHAMPIONS_REGULATION,
  now: Date = new Date(),
): RegulationStatus {
  const start = utcDate(reg.start).getTime();
  const end = utcDate(reg.end).getTime();
  const t = now.getTime();
  const phase: RegulationPhase = t < start ? 'upcoming' : t >= end ? 'ended' : 'active';
  const daysLeft = Math.ceil((end - t) / DAY_MS);
  const season = reg.seasons.find(s => t >= utcDate(s.start).getTime() && t < utcDate(s.end).getTime());
  return season ? { phase, daysLeft, season } : { phase, daysLeft };
}

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

/** 'Sep 9 – Dec 2, 2026' — the regulation's window as players see it listed. */
export function formatRegulationWindow(reg: ChampionsRegulation = CHAMPIONS_REGULATION): string {
  const s = utcDate(reg.start);
  const e = utcDate(reg.end);
  const sm = `${MONTHS[s.getUTCMonth()]} ${s.getUTCDate()}`;
  const em = `${MONTHS[e.getUTCMonth()]} ${e.getUTCDate()}`;
  return s.getUTCFullYear() === e.getUTCFullYear()
    ? `${sm} – ${em}, ${e.getUTCFullYear()}`
    : `${sm}, ${s.getUTCFullYear()} – ${em}, ${e.getUTCFullYear()}`;
}

/** One line for the filter panel: what the preset is and whether it is current. */
export function regulationNote(
  reg: ChampionsRegulation = CHAMPIONS_REGULATION,
  now: Date = new Date(),
): string {
  const { phase, daysLeft, season } = regulationStatus(reg, now);
  const window = formatRegulationWindow(reg);
  if (phase === 'upcoming') return `${reg.label} starts ${window.split(' – ')[0]} · ${reg.ids.length} usable`;
  if (phase === 'ended') return `${reg.label} ended ${window.split(' – ')[1]} — a newer regulation is likely live; this list may be stale`;
  const seasonBit = season ? ` · Season ${season.id.toUpperCase()}` : '';
  return `${reg.label} · ${window}${seasonBit} · ${daysLeft} day${daysLeft === 1 ? '' : 's'} left · ${reg.ids.length} usable`;
}
